import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  PieChart,
  Pie,
  Cell,
  Tooltip,
  ResponsiveContainer,
} from "recharts";

function Dashboard() {
  const navigate = useNavigate();

  const [username, setUsername] = useState("");
  const [transactions, setTransactions] = useState([]);
  const [amount, setAmount] = useState("");
  const [type, setType] = useState("Income");
  const [category, setCategory] = useState("");

  useEffect(() => {
    const storedUser = localStorage.getItem("username");
    if (!storedUser) {
      navigate("/");
    } else {
      setUsername(storedUser);
    }
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem("username");
    navigate("/");
  };

  const handleAddTransaction = () => {
    if (!amount || !category) return;

    const newTransaction = {
      id: Date.now(),
      amount: Number(amount),
      type,
      category,
    };

    setTransactions([...transactions, newTransaction]);
    setAmount("");
    setCategory("");
  };

  const handleDelete = (id) => {
    setTransactions(transactions.filter((t) => t.id !== id));
  };

  const income = transactions
    .filter((t) => t.type === "Income")
    .reduce((acc, t) => acc + t.amount, 0);

  const expenses = transactions
    .filter((t) => t.type === "Expense")
    .reduce((acc, t) => acc + t.amount, 0);

  const savings = income - expenses;

  const pieData = [
    { name: "Income", value: income },
    { name: "Expenses", value: expenses },
  ];

  const COLORS = ["#16a34a", "#dc2626"];

  return (
    <div className="min-h-screen flex bg-gradient-to-br from-sky-300 via-purple-200 to-purple-400">

      {/* Sidebar */}
      <div className="w-64 bg-white shadow-lg p-6 hidden md:block">
        <h2 className="text-2xl font-bold text-purple-700 mb-6">
          Finance App
        </h2>
        <ul className="space-y-4 text-gray-700">
          <li className="font-semibold text-purple-600">Dashboard</li>
          <li>Transactions</li>
          <li>Goals</li>
          <li onClick={handleLogout} className="cursor-pointer text-red-500">
            Logout
          </li>
        </ul>
      </div>

      {/* Main Content */}
      <div className="flex-1 p-6">

        {/* Header */}
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold text-purple-700">
            Welcome, {username} 👋
          </h1>
        </div>

        {/* Summary Cards */}
        <div className="grid md:grid-cols-3 gap-6 mb-8">
          <div className="bg-white p-6 rounded-2xl shadow-lg">
            <h2 className="text-gray-500">Total Income</h2>
            <p className="text-2xl font-bold text-green-600">₹{income}</p>
          </div>

          <div className="bg-white p-6 rounded-2xl shadow-lg">
            <h2 className="text-gray-500">Total Expenses</h2>
            <p className="text-2xl font-bold text-red-600">₹{expenses}</p>
          </div>

          <div className="bg-white p-6 rounded-2xl shadow-lg">
            <h2 className="text-gray-500">Savings</h2>
            <p className="text-2xl font-bold text-blue-600">₹{savings}</p>
          </div>
        </div>

        {/* Add Transaction */}
        <div className="bg-white p-6 rounded-2xl shadow-lg mb-8">
          <h2 className="text-xl font-bold mb-4 text-purple-700">
            Add Transaction
          </h2>

          <div className="grid md:grid-cols-4 gap-4">
            <input
              type="number"
              placeholder="Amount"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              className="border p-2 rounded-lg"
            />

            <select
              value={type}
              onChange={(e) => setType(e.target.value)}
              className="border p-2 rounded-lg"
            >
              <option>Income</option>
              <option>Expense</option>
            </select>

            <input
              type="text"
              placeholder="Category"
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              className="border p-2 rounded-lg"
            />

            <button
              onClick={handleAddTransaction}
              className="bg-purple-600 text-white rounded-lg px-4"
            >
              Add
            </button>
          </div>
        </div>

        {/* Chart */}
        <div className="bg-white p-6 rounded-2xl shadow-lg mb-8">
          <h2 className="text-xl font-bold mb-4 text-purple-700">
            Income vs Expenses
          </h2>

          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={pieData}
                dataKey="value"
                outerRadius={100}
                label
              >
                {pieData.map((entry, index) => (
                  <Cell key={index} fill={COLORS[index]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>

        {/* Transactions List */}
        <div className="bg-white p-6 rounded-2xl shadow-lg">
          <h2 className="text-xl font-bold mb-4 text-purple-700">
            Recent Transactions
          </h2>

          {transactions.length === 0 ? (
            <p className="text-gray-500">No transactions yet.</p>
          ) : (
            <ul className="space-y-3">
              {transactions.map((t) => (
                <li
                  key={t.id}
                  className="flex justify-between items-center border-b pb-2"
                >
                  <div>
                    <p className="font-semibold">{t.category}</p>
                    <p
                      className={
                        t.type === "Income"
                          ? "text-green-600"
                          : "text-red-600"
                      }
                    >
                      {t.type} ₹{t.amount}
                    </p>
                  </div>

                  <button
                    onClick={() => handleDelete(t.id)}
                    className="text-red-500"
                  >
                    Delete
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>

      </div>
    </div>
  );
}

export default Dashboard;
